G=load(); print(sorted(G), len(G))

def f(g):
    import copy
    out=[r[:] for r in g]; H=len(g); W=len(g[0])
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    colors=set(x for r in g for x in r)-{bg}
    seen=set()
    for i in range(H):
        for j in range(W):
            if g[i][j] in colors and (i,j) not in seen:
                c=g[i][j]; stack=[(i,j)]; comp=set()
                while stack:
                    a,b=stack.pop()
                    if (a,b) in comp: continue
                    comp.add((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and g[na][nb]==c and (na,nb) not in comp: stack.append((na,nb))
                seen|=comp
                rs=[a for a,_ in comp]; cs=[b for _,b in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                # flood fill outside to detect enclosed cells
                border=(g[r0][c0]==c and g[r1][c1]==c)
                if not border: continue
                outside=set(); stack=[(0,0)]
                while stack:
                    a,b=stack.pop()
                    if (a,b) in outside or out[a][b]==c: continue
                    outside.add((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and (na,nb) not in outside and out[na][nb]!=c: stack.append((na,nb))
                for a in range(r0+1,r1):
                    for b in range(c0+1,c1):
                        if (a,b) not in outside and out[a][b]!=c:
                            out[a][b]=7
    return out
